const source = $('Execute Workflow Trigger').item.json || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractFolderName(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'xoa folder',
    'xoa thu muc',
    'bo folder vao thung rac',
    'delete folder',
    'delete directory',
    'move folder to trash',
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanName(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const folderId =
  source.folderId ||
  source.targetId ||
  payload.folderId ||
  payload.targetId ||
  '';

const folderName = cleanName(
  source.folderName ||
  source.targetName ||
  payload.folderName ||
  payload.targetName ||
  extractFolderName(raw)
);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    folderId,
    targetId: folderId,
    folderName,
    targetName: folderName,

    hasTarget: Boolean(folderId || folderName),

    response: folderId || folderName
      ? ''
      : '🗑️ <b>Xóa folder</b>\n\nVí dụ:\n<code>xóa folder test_n8n</code>',
  },
}];

const source = $('Prepare Action').item.json || {};
const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      targetId: '',
      response: 'Không tìm thấy file/folder phù hợp với: <i>' + String(source.targetName || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</i>'
    }
  }];
}

const target = rows[0];

return [{
  json: {
    ...source,
    ...target,
    targetId: target.id || source.targetId || source.folderId || source.fileId || '',
    targetName: target.name || source.targetName || source.folderName || source.fileName || '',
    webViewLink: target.webViewLink || source.webViewLink || '',
    mimeType: target.mimeType || source.mimeType || ''
  }
}];

const source = $('Prepare Action').item.json || {};
const current = $input.item.json || {};

const targetId =
  current.targetId ||
  current.folderId ||
  current.fileId ||
  current.id ||
  source.targetId ||
  source.folderId ||
  source.fileId ||
  '';

if (!targetId) {
  return [{
    json: {
      ...source,
      response: 'Không tìm thấy ID file/folder để đưa vào thùng rác.'
    }
  }];
}

return [{
  json: {
    ...source,
    ...current,
    targetId,
    targetName: current.name || current.targetName || source.targetName || source.folderName || source.fileName || ''
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const name = item.name || item.targetName || source.targetName || source.folderName || source.fileName || 'Không rõ tên';
const id = item.id || item.targetId || source.targetId || source.folderId || source.fileId || '';
const link = item.webViewLink || source.webViewLink || '';
const isFolder = item.mimeType === 'application/vnd.google-apps.folder' || source.mode === 'folder';
const trashed = item.trashed === true;

let text = trashed
  ? '🗑️ <b>Đã đưa ' + (isFolder ? 'folder' : 'file') + ' vào thùng rác</b>\n\n'
  : '⚠️ <b>Chưa xác nhận được đã vào thùng rác</b>\n\n';

text += (isFolder ? '📁 ' : '📄 ') + '<b>' + escapeHtml(name) + '</b>\n';

if (id) {
  text += 'ID: <code>' + escapeHtml(id) + '</code>\n';
}

if (link) {
  text += '🔗 <a href="' + escapeHtml(link) + '">Mở trong Drive</a>\n';
}

if (!trashed) {
  text += '\nOutput không có <code>trashed: true</code>. Hãy kiểm tra lại credential hoặc node trash.';
}

return [{
  json: {
    chatId: source.chatId || item.chatId,
    text: text.trim()
  }
}];
